  ARR["Transaction Arrives from Port A (or Port B)"] --> FIND{"match_table.exists(item.id)?"}
  FIND -->|No: First Arrival| STORE["Allocate entry in match_table[id]<br/>Set has_a = 1 (or has_b = 1)<br/>Store cloned handle & arrival_time = $time"]
  FIND -->|Yes: Entry Exists| CHK_SIDE{"Check Presence Flags"}
  CHK_SIDE -->|Same Port: has_a is 1| ERR_DUP["UVM_ERROR: Duplicate Packet on Port A<br/>(Protocol violation / stale ID collision)"]
  CHK_SIDE -->|Opposite Port: has_b is 1| MATCH["Legitimate Partner Match!<br/>Compare Port A vs Port B payloads<br/>Delete entry from match_table (enables clean ID reuse)<br/>Increment matched_count"]

  subgraph WD ["Timeout Watchdog"]
    CHECK["run_phase() Periodic Watchdog"] --> SCAN["Scan pending entries in match_table"]
    SCAN --> EXP{"($time - arrival_time) > TIMEOUT_LIMIT?"}
    EXP -->|Yes| ERR_TO["UVM_ERROR: Transaction Timeout<br/>Log orphan ID and origin port<br/>Delete expired entry from match_table"]
    EXP -->|No| OK["Keep waiting"]
  end

