    EOT["check_phase()"] --> EMPTY{"match_table.num() == 0?"}
    EMPTY -->|Yes| PASS["Test Passed: Zero hanging transactions"]
    EMPTY -->|No| FAIL["UVM_ERROR: Unpaired transactions remain"]
  end
```

### Code
```systemverilog
class paired_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(paired_scoreboard)

  // Tracking structure with explicit presence flags
  typedef struct {
    bit        has_a;
    bit        has_b;
    trans_item item_a;
    trans_item item_b;
    time       arrival_time;
  } pair_entry_t;

  pair_entry_t match_table[int];
  int matched_count;
  int timeout_count;
  time timeout_limit = 100us;

  `uvm_analysis_imp_decl(_port_a)
  `uvm_analysis_imp_decl(_port_b)

  uvm_analysis_imp_port_a #(trans_item, paired_scoreboard) imp_a;
  uvm_analysis_imp_port_b #(trans_item, paired_scoreboard) imp_b;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    imp_a = new("imp_a", this);
    imp_b = new("imp_b", this);
  endfunction

  virtual function void write_port_a(trans_item item);
    int id = item.id;
    if (!match_table.exists(id)) begin
      pair_entry_t entry;
      entry.has_a        = 1'b1;
      entry.has_b        = 1'b0;
      $cast(entry.item_a, item.clone()); // Prevent monitor handle reuse corruption
      entry.arrival_time = $time;
      match_table[id]    = entry;
    end else begin
      if (match_table[id].has_a) begin
        // Duplicate from same port: flag error, do NOT treat as match!
        `uvm_error("SCB_DUP_A", $sformatf("Duplicate transaction received on Port A for ID %0d (original arrived at %0t)",
                   id, match_table[id].arrival_time))
      end else if (match_table[id].has_b) begin
        // Opposite port arrived earlier: legitimate match
        compare_trans(item, match_table[id].item_b, id);
        match_table.delete(id); // Clear entry to permit clean ID reuse
        matched_count++;
      end
    end
  endfunction

  virtual function void write_port_b(trans_item item);
    int id = item.id;
    if (!match_table.exists(id)) begin
      pair_entry_t entry;
      entry.has_a        = 1'b0;
      entry.has_b        = 1'b1;
      $cast(entry.item_b, item.clone()); // Prevent monitor handle reuse corruption
      entry.arrival_time = $time;
      match_table[id]    = entry;
    end else begin
      if (match_table[id].has_b) begin
        // Duplicate from same port: flag error, do NOT treat as match!
        `uvm_error("SCB_DUP_B", $sformatf("Duplicate transaction received on Port B for ID %0d (original arrived at %0t)",
                   id, match_table[id].arrival_time))
      end else if (match_table[id].has_a) begin
        // Opposite port arrived earlier: legitimate match
        compare_trans(match_table[id].item_a, item, id);
        match_table.delete(id); // Clear entry to permit clean ID reuse
        matched_count++;
      end
    end
  endfunction

  virtual function void compare_trans(trans_item a, trans_item b, int id);
    if (!a.compare(b))
      `uvm_error("SCB_MISMATCH", $sformatf("Data payload mismatch on paired ID %0d", id))
  endfunction

  // Periodic Watchdog: Flags timeouts and deletes expired entries to allow ID reuse
  virtual task run_phase(uvm_phase phase);
    int expired_keys[$];
    forever begin
      #10us;
      expired_keys.delete();
      foreach (match_table[id]) begin
        if (($time - match_table[id].arrival_time) > timeout_limit) begin
          string src = match_table[id].has_a ? "Port A" : "Port B";
          `uvm_error("SCB_TIMEOUT", $sformatf("Timeout on ID %0d: partner failed to arrive within %0t (orphan from %s arrived at %0t)",
                     id, timeout_limit, src, match_table[id].arrival_time))
          expired_keys.push_back(id);
          timeout_count++;
        end
      end
      // Delete expired entries to unblock subsequent ID reuse and prevent memory leaks
      foreach (expired_keys[i])
        match_table.delete(expired_keys[i]);
    end
  endtask

  virtual function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    if (match_table.num() != 0) begin
      foreach (match_table[id]) begin
        string src = match_table[id].has_a ? "Port A" : "Port B";
        `uvm_error("SCB_LEAK", $sformatf("Unpaired orphan transaction remains at end of test: ID %0d from %s (arrived %0t)",
                   id, src, match_table[id].arrival_time))
      end
    end
  endfunction
endclass
```

### Explanation
- **Why `table.exists()` Alone Fails:** If an unexpected duplicate transaction arrives on Port A with the same ID, `match_table.exists(id)` evaluates to true. Without presence bits (`has_a`, `has_b`), the scoreboard mistakenly assumes Port B arrived and compares Port A against Port A, masking the protocol error.
- **Presence Flags & State Validation:** The `pair_entry_t` record tracks which specific port has arrived. Duplicate arrivals on the same port trigger an immediate `SCB_DUP_*` error.
- **Handle Cloning:** Monitored items passed to analysis ports are often reused by monitors. Calling `$cast(entry.item, item.clone())` guarantees the stored object is immutable and unaffected by subsequent monitor cycles.
- **ID Reuse & Timeout Management:** When a pair matches, `match_table.delete(id)` frees the key, allowing future transactions to safely reuse that ID. Similarly, when the watchdog detects an orphan transaction exceeding `timeout_limit`, it logs a timeout error and removes the entry, preventing stale state from corrupting subsequent transfers with the same ID.

### Corner cases & pitfalls
- **ID Reuse Before Timeout:** If an ID is reused while an orphan entry is still pending, the arrival on the same port is caught by the duplicate check, exposing insufficient ID space or an undersized timeout window.
- **Associative Array Memory Growth:** Unmatched entries left indefinitely in the table cause simulation memory footprint to grow continuously; watchdog retirement prevents memory exhaustion during long regression runs.

### Follow-ups
- How to handle multiple outstanding transactions with identical IDs? Use queues of entries per ID (`pair_entry_t match_table[int][$]`) if the protocol allows out-of-order pipelined duplicate IDs.
- What if arrival order is deterministic? A simple FIFO queue pair (`uvm_tlm_fifo`) can replace the associative table.

