// NOTE: Architectural model and matching algorithm (partial pseudocode).
// Illustrates per-ID FIFO queues, AW/W burst assembly, and out-of-order handling.

class axi_scoreboard_pseudocode extends uvm_scoreboard;
  `uvm_component_utils(axi_scoreboard_pseudocode)

  // Associative arrays of queues indexed by transaction ID
  axi_write_exp expected_wr_b_q[int][$]; // Expected write responses per AWID/BID
  axi_read_exp  expected_rd_q[int][$];   // Expected read bursts per ARID/RID

  // Ingestion assembly FIFOs for Write Channel (AXI4 has no WID)
  axi_aw_item aw_fifo[$];
  axi_w_burst w_burst_fifo[$];
  axi_w_burst curr_w_burst;

  // Analysis implementation exports for all 5 AXI channels
  `uvm_analysis_imp_decl(_aw)
  `uvm_analysis_imp_decl(_w)
  `uvm_analysis_imp_decl(_b)
  `uvm_analysis_imp_decl(_ar)
  `uvm_analysis_imp_decl(_r)

  uvm_analysis_imp_aw #(axi_aw_item, axi_scoreboard_pseudocode) aw_export;
  uvm_analysis_imp_w  #(axi_w_item,  axi_scoreboard_pseudocode) w_export;
  uvm_analysis_imp_b  #(axi_b_item,  axi_scoreboard_pseudocode) b_export;
  uvm_analysis_imp_ar #(axi_ar_item, axi_scoreboard_pseudocode) ar_export;
  uvm_analysis_imp_r  #(axi_r_item,  axi_scoreboard_pseudocode) r_export;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    aw_export = new("aw_export", this);
    w_export  = new("w_export",  this);
    b_export  = new("b_export",  this);
    ar_export = new("ar_export", this);
    r_export  = new("r_export",  this);
  endfunction

  // 1. Write Address Intake
  virtual function void write_aw(axi_aw_item item);
    axi_aw_item cloned;
    $cast(cloned, item.clone());
    aw_fifo.push_back(cloned);
    try_assemble_write();
  endfunction

  // 2. Write Data Intake: In AXI4, W has no WID; data bursts arrive in FIFO order with AW
  virtual function void write_w(axi_w_item item);
    curr_w_burst.beats.push_back(item);
    if (item.wlast) begin
      w_burst_fifo.push_back(curr_w_burst);
      curr_w_burst.beats.delete();
      try_assemble_write();
    end
  endfunction

  // Assemble AW and W burst, evaluate with reference model (cannot assume OKAY)
  virtual function void try_assemble_write();
    while (aw_fifo.size() > 0 && w_burst_fifo.size() > 0) begin
      axi_aw_item aw = aw_fifo.pop_front();
      axi_w_burst w  = w_burst_fifo.pop_front();

      // Reference model predicts response (OKAY, SLVERR, or DECERR based on address/decode)
      axi_write_exp exp = ref_model.predict_write(aw, w);
      expected_wr_b_q[aw.id].push_back(exp);
    end
  endfunction

  // 3. Write Response Matching: Out-of-order across IDs, strict FIFO for same ID
  virtual function void write_b(axi_b_item act);
    if (!expected_wr_b_q.exists(act.id) || expected_wr_b_q[act.id].size() == 0) begin
      `uvm_error("SCB_UNEXP_BID", $sformatf("Unexpected BID=0x%0h received", act.id))
      return;
    end
    begin
      axi_write_exp exp = expected_wr_b_q[act.id].pop_front();
      if (act.resp != exp.resp)
        `uvm_error("SCB_BRESP_MISMATCH", $sformatf("Mismatch on ID 0x%0h: Act=%0s Exp=%0s", act.id, act.resp.name(), exp.resp.name()))
    end
  endfunction

  // 4. Read Address Intake: Predict read burst data and response beats
  virtual function void write_ar(axi_ar_item item);
    axi_read_exp exp_burst = ref_model.predict_read(item);
    expected_rd_q[item.id].push_back(exp_burst);
  endfunction

  // 5. Read Data Matching: Same-ID bursts cannot interleave; only different IDs can interleave
  virtual function void write_r(axi_r_item act);
    if (!expected_rd_q.exists(act.id) || expected_rd_q[act.id].size() == 0) begin
      `uvm_error("SCB_UNEXP_RID", $sformatf("Unexpected RID=0x%0h received", act.id))
      return;
    end
    begin
      // Front of queue is the active burst for this ID (same ID cannot interleave)
      axi_read_exp exp_burst = expected_rd_q[act.id][0];
      exp_burst.compare_beat(act);

      if (act.rlast) begin
        if (!exp_burst.is_last_beat())
          `uvm_error("SCB_RLAST_MISMATCH", $sformatf("Premature RLAST on ID 0x%0h", act.id))
        void'(expected_rd_q[act.id].pop_front());
      end
    end
  endfunction

  virtual function void check_phase(uvm_phase phase);
    super.check_phase(phase);
    foreach (expected_wr_b_q[id]) begin
      if (expected_wr_b_q[id].size() != 0)
        `uvm_error("SCB_WR_LEAK", $sformatf("Hanging write ID 0x%0h (%0d items unreturned)", id, expected_wr_b_q[id].size()))
    end
    foreach (expected_rd_q[id]) begin
      if (expected_rd_q[id].size() != 0)
        `uvm_error("SCB_RD_LEAK", $sformatf("Hanging read ID 0x%0h (%0d items unreturned)", id, expected_rd_q[id].size()))
    end
  endfunction
