    axi_config_seq  cfg_seq  = axi_config_seq::type_id::create("cfg_seq");
    axi_write_seq   wr_seq   = axi_write_seq::type_id::create("wr_seq");
    spi_monitor_seq spi_seq  = spi_monitor_seq::type_id::create("spi_seq");

    `uvm_info("VSEQ", "Phase 1: Configuring SPI controller via AXI", UVM_LOW)
    cfg_seq.start(axi_sqr);

